-- create policy ... using (... public.is_admin()) again for: colleges_admin, amenities_admin, bh_delete, reviews_delete, pay_read, boost_read,
--   audit_admin_read, ai_chat_log_admin_read, ai_unanswered_admin_read, ai_feedback_read, banned_identities_admin_read, br_read, ua_read, ov_read,
--   idv_read (storage). The exact old text is in the "-- from" migrations 001, 003, 005, 014, 020, 023.
